code.source:
for n in range(1, 10):
    if n == 4:
        print("Stop at 4")
        break
    print("n is", n)

for n in range(1, 6):
    if n % 2 == 0:
        continue
    print("Odd:", n)
else:
    print("Loop finished without break")

